n class="btn-success" onclick="saveFile()">Save</button></div></dialog><script>const api=async(data)=>{const res=await fetch('',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)});return res.json();};function navigate(enc){window.location.href='?d='+enc;}async function editFile(name){const res=await api({action:'get_content',name:name});if(res.success){document.getElementById('editTitle').innerText='Editing:'+name;document.getElementById('editorContent').value=res.content;document.getElementById('editorDialog').showModal();}else{alert('Cannot read file');}}async function saveFile(){const name=document.getElementById('editTitle').innerText.replace('Editing:','');const content=document.getElementById('editorContent').value;const res=await api({action:'save_file',name:name,content:content});if(res.success){alert('File saved successfully');document.getElementById('editorDialog').close();location.reload();}else{alert('Error saving file');}}async function deleteItem(name){if(confirm('Delete '+name+'?')){await api({action:'delete',name:name});location.reload();}}async function newFolder(){const name=prompt('Enter folder name:');if(name){const res=await api({action:'new_folder',name:name});if(res.success){location.reload();}else{alert(res.message||'Error creating folder');}}}async function newFile(){const name=prompt('Enter file name:');if(name){const res=await api({action:'new_file',name:name});if(res.success){location.reload();}else{alert(res.message||'Error creating file');}}}async function uploadFile(){const input=document.createElement('input');input.type='file';input.onchange=async()=>{const file=input.files[0];const formData=new FormData();formData.append('action','upload');formData.append('file',file);const res=await fetch('',{method:'POST',body:formData});const data=await res.json();if(data.success){alert('File uploaded successfully');location.reload();}else{alert('Upload failed');}};input.click();}</script><